-- Additive fictional scenario documents only. No payment or original-row changes.
DO $care_consumer$
DECLARE expected jsonb := '[{"id":"00000000-0000-4000-8000-000000001201","twin_id":"00000000-0000-4000-8000-000000000201","kind":"care-card","origin":"sample","title":"Headphones price review · Demo source","content":"PAL CARE — DEMO CARE SCENARIO\nFictional evidence only. No real merchant action, shipment, refund or PayPal operation occurred. Original purchases and payment evidence are unchanged.\n{\n  \"version\": 1,\n  \"simulated\": true,\n  \"asOf\": \"2026-11-05T12:00:00.000Z\",\n  \"twinId\": \"00000000-0000-4000-8000-000000000201\",\n  \"documentId\": \"00000000-0000-4000-8000-000000001201\",\n  \"kind\": \"price-opportunity\",\n  \"paidMinor\": 14900,\n  \"previousMinor\": 14900,\n  \"currentMinor\": 12900,\n  \"eligibility\": \"needs-review\"\n}"},{"id":"00000000-0000-4000-8000-000000001206","twin_id":"00000000-0000-4000-8000-000000000206","kind":"care-card","origin":"sample","title":"Boots return progress · Demo source","content":"PAL CARE — DEMO CARE SCENARIO\nFictional evidence only. No real merchant action, shipment, refund or PayPal operation occurred. Original purchases and payment evidence are unchanged.\n{\n  \"version\": 1,\n  \"simulated\": true,\n  \"asOf\": \"2026-11-05T12:00:00.000Z\",\n  \"twinId\": \"00000000-0000-4000-8000-000000000206\",\n  \"documentId\": \"00000000-0000-4000-8000-000000001206\",\n  \"kind\": \"return-progress\",\n  \"milestones\": [\n    \"Return agreed · November 1\",\n    \"Parcel received · November 4\",\n    \"Inspection pending\"\n  ],\n  \"refundConfirmed\": false\n}"},{"id":"00000000-0000-4000-8000-000000001208","twin_id":"00000000-0000-4000-8000-000000000208","kind":"care-card","origin":"sample","title":"Book refund illustration · Demo source","content":"PAL CARE — DEMO CARE SCENARIO\nFictional evidence only. No real merchant action, shipment, refund or PayPal operation occurred. Original purchases and payment evidence are unchanged.\n{\n  \"version\": 1,\n  \"simulated\": true,\n  \"asOf\": \"2026-11-05T12:00:00.000Z\",\n  \"twinId\": \"00000000-0000-4000-8000-000000000208\",\n  \"documentId\": \"00000000-0000-4000-8000-000000001208\",\n  \"kind\": \"refund-illustration\",\n  \"amountMinor\": 2495,\n  \"completedOn\": \"2026-11-04\",\n  \"providerVerified\": false\n}"}]'::jsonb; r jsonb;
BEGIN
  FOR r IN SELECT value FROM jsonb_array_elements(expected) LOOP
    IF NOT EXISTS (SELECT 1 FROM purchase_twins t WHERE t.id=(r->>'twin_id')::uuid AND t.origin='sample' AND t.customer_id='00000000-0000-4000-8000-000000000001' AND t.merchant_id='00000000-0000-4000-8000-000000000002') THEN
      RAISE EXCEPTION 'consumer_demo_sample_binding_required';
    END IF;
    INSERT INTO documents(id,twin_id,kind,origin,title,content) SELECT id,twin_id,kind,origin,title,content FROM jsonb_populate_record(null::documents,r) ON CONFLICT(id) DO NOTHING;
    IF NOT EXISTS (SELECT 1 FROM documents d WHERE d.id=(r->>'id')::uuid AND to_jsonb(d)=to_jsonb(jsonb_populate_record(null::documents,r))) THEN
      RAISE EXCEPTION 'consumer_demo_document_conflict';
    END IF;
  END LOOP;
END $care_consumer$;
